import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const e=JSON.parse('{"title":"&quot;Không phải cuộc thi nào cũng đáng tham gia&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/cuoc-thi.md","filePath":"mental-models/cuoc-thi.md"}'),g={name:"mental-models/cuoc-thi.md"};function a(o,n,u,r,l,m){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="quot-khong-phai-cuoc-thi-nao-cung-đang-tham-gia-quot" tabindex="-1">&quot;Không phải cuộc thi nào cũng đáng tham gia&quot; <a class="header-anchor" href="#quot-khong-phai-cuoc-thi-nao-cung-đang-tham-gia-quot" aria-label="Permalink to &quot;&amp;quot;Không phải cuộc thi nào cũng đáng tham gia&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Không phải cuộc thi nào cũng đáng tham gia&quot; <a href="#khong-phai-cuoc-thi-nao-cung-đang-tham-gia">​</a> Mỗi cuộc thi có một cái giá: thời gian ôn, thời gian không dùng cho việc khác, áp lực, và rủi ro nếu trượt. Câu hỏi không phải &quot;cuộc thi này có tốt không&quot; — mà <strong>&quot;nó mua được gì cho con, và đổi bằng cái gì?&quot;</strong></p><h2 id="cai-gia-thuong-bi-bo-qua-​" tabindex="-1">Cái giá thường bị bỏ qua <a href="#cai-gia-thuong-bi-bo-qua">​</a> <a class="header-anchor" href="#cai-gia-thuong-bi-bo-qua-​" aria-label="Permalink to &quot;Cái giá thường bị bỏ qua [​](#cai-gia-thuong-bi-bo-qua)&quot;">​</a></h2><p>Khi cân nhắc một cuộc thi, phần được nhìn thấy là phần lợi: có giải thì đẹp hồ sơ, có động lực, có trải nghiệm. Phần chi phí thì mờ hơn: <strong>Thời gian trực tiếp.</strong> Ôn luyện cho một cuộc thi chuyên biệt thường tốn hàng chục tới hàng trăm giờ. <strong>Thứ đã mất đi để đổi lấy.</strong> Đây là chi phí thật, và nó gần như không bao giờ được tính. 80 giờ ôn thi là 80 giờ không dùng để vá lỗ hổng nền, không dùng cho một dự án cá nhân, không dùng để ngủ đủ. <strong>Nội dung hẹp.</strong> Nhiều cuộc thi đòi hỏi dạng bài rất riêng, ít dùng lại ở nơi khác. Kỹ năng thu được có thể không chuyển sang đâu cả. <strong>Rủi ro tâm lý.</strong> Một đứa trẻ dồn sáu tháng vào một cuộc thi rồi trượt sẽ chịu ảnh hưởng thật — nhất là khi cuộc thi đó là câu chuyện duy nhất của em ấy trong sáu tháng đó.</p><h2 id="sau-cau-hoi-truoc-khi-đang-ky-​" tabindex="-1">Sáu câu hỏi trước khi đăng ký <a href="#sau-cau-hoi-truoc-khi-đang-ky">​</a> <a class="header-anchor" href="#sau-cau-hoi-truoc-khi-đang-ky-​" aria-label="Permalink to &quot;Sáu câu hỏi trước khi đăng ký [​](#sau-cau-hoi-truoc-khi-đang-ky)&quot;">​</a></h2><ul><li><strong>Cuộc thi này phục vụ mảng nào trong Portrait của con?</strong> Nếu không phục vụ mảng nào, đó là tín hiệu đáng dừng lại suy nghĩ.</li><li><strong>Nội dung ôn có trùng với thứ con cần học không?</strong> Ôn thi mà đồng thời củng cố nền là một chuyện; ôn một dạng bài chỉ tồn tại trong cuộc thi đó là chuyện khác hẳn.</li><li><strong>Ai muốn cuộc thi này?</strong> Con, bố mẹ, hay nhà trường? Cả ba đều là câu trả lời hợp lệ — nhưng cần biết câu trả lời thật.</li><li><strong>Trượt thì sao?</strong> Nếu câu trả lời là &quot;sụp đổ&quot;, cuộc thi đang quá lớn so với chỗ nó nên chiếm.</li><li><strong>80 giờ đó có thể dùng vào việc gì khác?</strong> So sánh cụ thể, không so chung chung.</li><li><strong>Con còn năng lượng cho những thứ khác không?</strong> Một đứa trẻ đang ôn ba cuộc thi cùng lúc không thật sự tham gia cuộc thi nào.</li></ul><h2 id="khi-mot-cuoc-thi-đang-tham-gia-​" tabindex="-1">Khi một cuộc thi đáng tham gia <a href="#khi-mot-cuoc-thi-đang-tham-gia">​</a> <a class="header-anchor" href="#khi-mot-cuoc-thi-đang-tham-gia-​" aria-label="Permalink to &quot;Khi một cuộc thi đáng tham gia [​](#khi-mot-cuoc-thi-đang-tham-gia)&quot;">​</a></h2><p>Không phải bài này chống lại các cuộc thi. Có những trường hợp giá trị rất rõ: <strong>Khi nó khớp với hướng đi.</strong> Một learner mê lập trình tham gia cuộc thi lập trình — nội dung ôn chính là thứ em ấy muốn học, và sẽ học kể cả khi không có cuộc thi. <strong>Khi nó tạo ra một hạn chót có ích.</strong> Nhiều learner học tốt hơn hẳn khi có một mốc thật. Cuộc thi cung cấp cấu trúc mà việc học tự do không có. <strong>Khi nó mở ra cánh cửa cụ thể.</strong> Một số cuộc thi thật sự dẫn tới học bổng, tuyển thẳng, hoặc cộng đồng đáng tham gia. Đây là giá trị có thật, cần kiểm chứng chứ không nên tin theo lời đồn. <strong>Khi trải nghiệm tự nó là giá trị.</strong> Đi thi xa, gặp những bạn giỏi hơn mình nhiều, biết mình đang ở đâu trong một thế giới rộng hơn — với một số đứa trẻ, đây là bước ngoặt.</p><h2 id="ba-dau-hieu-nen-dung-lai-​" tabindex="-1">Ba dấu hiệu nên dừng lại <a href="#ba-dau-hieu-nen-dung-lai">​</a> <a class="header-anchor" href="#ba-dau-hieu-nen-dung-lai-​" aria-label="Permalink to &quot;Ba dấu hiệu nên dừng lại [​](#ba-dau-hieu-nen-dung-lai)&quot;">​</a></h2><p><strong>Sưu tập giải thưởng.</strong> Tham gia mọi cuộc thi có thể, với hy vọng danh sách dài sẽ có ích. Hồ sơ tuyển sinh tốt thường sâu chứ không dài, và một danh sách dài mà nông thường phản tác dụng. <strong>Ôn thi thay cho học.</strong> Khi toàn bộ thời gian là luyện dạng đề, learner có thể đạt điểm cao trong cuộc thi đó mà nền vẫn hổng. Điều này lộ ra một hai năm sau, ở một chỗ khác. <strong>Con không biết vì sao mình thi.</strong> Nếu hỏi &quot;vì sao con thi cái này&quot; mà câu trả lời là &quot;bố mẹ bảo thế&quot;, cuộc thi vẫn có thể có ích — nhưng cần biết là nó đang chạy bằng động lực của người khác, và động lực đó sẽ cạn.</p><h2 id="nemo12-nhin-cuoc-thi-the-nao-​" tabindex="-1">Nemo12 nhìn cuộc thi thế nào <a href="#nemo12-nhin-cuoc-thi-the-nao">​</a> <a class="header-anchor" href="#nemo12-nhin-cuoc-thi-the-nao-​" aria-label="Permalink to &quot;Nemo12 nhìn cuộc thi thế nào [​](#nemo12-nhin-cuoc-thi-the-nao)&quot;">​</a></h2><p>Cuộc thi là <strong>một loại mục tiêu</strong> — có ngày, có yêu cầu, có mức sẵn sàng đo được. Khi gia đình chốt tham gia, nó trở thành mục tiêu thật và hệ thống bắt đầu tính khoảng cách tới nó. Nhưng hệ thống cũng làm hai việc mà một trung tâm luyện thi thường không làm:</p><ul><li><strong>Chỉ ra xung đột.</strong> Hai mục tiêu cùng tranh thời gian sẽ được nêu rõ, kèm con số. Không ai bị bất ngờ vào phút chót.</li><li><strong>Bảo vệ phần nền.</strong> Nếu ôn thi đang khiến những mắt xích nền quan trọng bị bỏ rơi, điều đó được nêu ra — vì cái giá của nó sẽ hiện ra sau kỳ thi, không phải trước. Câu hỏi thay thế Thay vì <em>&quot;cuộc thi này có tốt không?&quot;</em> — hỏi: <strong>&quot;Nếu con không thi cái này, 80 giờ đó dùng vào việc gì? Việc đó có giá trị hơn không?&quot;</strong> Câu hỏi này khó hơn, và nó thường cho câu trả lời rõ ràng hơn nhiều. Một cuộc thi đáng tham gia khi nó phục vụ hướng đi của con. Không đáng khi nó chỉ phục vụ nhu cầu có gì đó để nói. <a href="/mental-models/muc-tieu-cuoi">Mục tiêu cuối cùng không chỉ là thi đỗ →</a></li></ul>',13)])])}const k=h(g,[["render",a]]);export{e as __pageData,k as default};
